#!/usr/bin/env bash\nset -e\n\n# Mock `uptime` to return minutes only\nTMPDIR=$(mktemp -d)\ncat > "$TMPDIR/uptime" <<'EOF'\n#!/usr/bin/env bash\necho "up 5 minutes"\nEOF\nchmod +x "$TMPDIR/uptime"\nexport PATH="$TMPDIR:$PATH"\n\nSCRIPT_DIR=$(cd "$(dirname \"${BASH_SOURCE[0]}\")/../src" && pwd)\noutput=$(bash "$SCRIPT_DIR/uptime-emoji.sh")\n\n# Expect only the minute emoji and no others\nif [[ "$output" != *"🕒"* ]]; then\n  echo "Test failed: minute emoji missing"\n  exit 1\nfi\nif [[ "$output" == *"🌞"* ]] || [[ "$output" == *"⏰"* ]]; then\n  echo "Test failed: unexpected day/hour emojis present"\n  exit 1\nfi\n\n# Verify the textual part\nif [[ "$output" != *"5 minutes"* ]]; then\n  echo "Test failed: minutes text missing"\n  exit 1\nfi\n\necho "Test passed: minutes‑only uptime with correct emoji"\n
